import assert from 'node:assert/strict';
import { SpanKind, SpanStatusCode, context, trace } from '@opentelemetry/api';
import { SeverityNumber } from '@opentelemetry/api-logs';
import { resourceFromAttributes } from '@opentelemetry/resources';
import { BasicTracerProvider, InMemorySpanExporter, SimpleSpanProcessor } from '@opentelemetry/sdk-trace-base';
import { InMemoryLogRecordExporter, LoggerProvider, SimpleLogRecordProcessor } from '@opentelemetry/sdk-logs';
import { AggregationTemporality, MeterProvider, MetricReader } from '@opentelemetry/sdk-metrics';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-proto';
import { OTLPLogExporter } from '@opentelemetry/exporter-logs-otlp-proto';
import { OTLPMetricExporter } from '@opentelemetry/exporter-metrics-otlp-http';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// The on-call engineer reads what was sent through HyperDX's External API v2, with the personal API key the World issued.
const api = async (path, body) => {
  const r = await fetch(`${process.env.HYPERDX_API_URL}${path}`, { method: body ? 'POST' : 'GET', headers: { authorization: `Bearer ${process.env.HYPERDX_API_ACCESS_KEY}`, ...(body ? { 'content-type': 'application/json' } : {}) }, ...(body ? { body: JSON.stringify(body) } : {}), signal: AbortSignal.timeout(10_000) });
  assert.equal(r.status, 200, `${path}: ${await r.clone().text()}`);
  return r.json();
};
const sourceIds = async () => { const { data } = await api('/api/v2/sources'); return { traces: data.find((s) => s.kind === 'trace').id, logs: data.find((s) => s.kind === 'log').id }; };
if (process.argv[2] === 'readback') {
  // after the World resumes: the kept trace's server span, read without writing
  const { traces } = await sourceIds();
  const now = Date.now();
  const { data } = await api('/api/v2/search', { sourceId: traces, startTime: new Date(now - 30 * 864e5).toISOString(), endTime: new Date(now + 864e5).toISOString(), where: 'SpanName:"POST /api/*" AND ServiceName:"librechat"', select: 'TraceId,SpanName,Duration,StatusCode' });
  assert.ok(data.length >= 1);
  assert.equal(data[0].StatusCode, 'Error');
  assert.equal(data[0].Duration, '850000000');
  console.log(JSON.stringify({ readback: data[0].TraceId }));
  process.exit(0);
}
// LibreChat's server telemetry (LibreChat-AI/LibreChat f10b1d91, packages/api/src/telemetry): its NodeSDK exports spans
// and Winston log records with the OTLP/HTTP protobuf exporters (OTEL_EXPORTER_OTLP_PROTOCOL's default), at
// OTEL_EXPORTER_OTLP_ENDPOINT, which the exporters read themselves; Twenty's metrics (twentyhq/twenty 1d561b8c,
// packages/twenty-server/src/instrument.ts) go through the JSON metric exporter at OTLP_COLLECTOR_METRICS_ENDPOINT_URL
// with delta temporality (its METER_TEMPORALITY default).
assert.ok(process.env.OTEL_EXPORTER_OTLP_ENDPOINT, 'the World points OTEL_EXPORTER_OTLP_ENDPOINT at its OTLP receiver');
assert.ok(process.env.OTLP_COLLECTOR_METRICS_ENDPOINT_URL?.endsWith('/v1/metrics'));
const SUCCESS = 0;
const exported = (exporter, items) => new Promise((resolve) => exporter.export(items, resolve));

// a failed chat request: the server span, its MongoDB child, the exception it records, and the error log inside it
const spans = new InMemorySpanExporter();
const tracer = new BasicTracerProvider({ resource: resourceFromAttributes({ 'service.name': 'librechat' }), spanProcessors: [new SimpleSpanProcessor(spans)] }).getTracer('@opentelemetry/instrumentation-http', '0.207.0');
const logs = new InMemoryLogRecordExporter();
const logger = new LoggerProvider({ resource: resourceFromAttributes({ 'service.name': 'librechat' }), processors: [new SimpleLogRecordProcessor(logs)] }).getLogger('@opentelemetry/winston-transport', '0.28.0');
const t0 = Date.now();
const server = tracer.startSpan('POST /api/*', { kind: SpanKind.SERVER, startTime: t0, attributes: { 'http.request.method': 'POST', 'url.path': '/api/*' } });
const ctx = trace.setSpan(context.active(), server);
const db = tracer.startSpan('mongodb.insert', { kind: SpanKind.CLIENT, startTime: t0 + 120, attributes: { 'db.system.name': 'mongodb', 'db.collection.name': 'messages' } }, ctx);
const error = Object.assign(new Error('connection 4 to 127.0.0.1:27017 closed'), { name: 'MongoNetworkError' });
db.setStatus({ code: SpanStatusCode.ERROR, message: error.message }); db.end(t0 + 835);
server.recordException(error);
server.setStatus({ code: SpanStatusCode.ERROR, message: error.message });
logger.emit({ severityNumber: SeverityNumber.ERROR, severityText: 'error', body: `[saveMessage] Error saving message: ${error.message}`, context: ctx });
server.setAttribute('http.response.status_code', 500); server.end(t0 + 850);

const traceResult = await exported(new OTLPTraceExporter(), spans.getFinishedSpans());
assert.equal(traceResult.code, SUCCESS, `trace export: ${traceResult.error}`);
const logResult = await exported(new OTLPLogExporter(), logs.getFinishedLogRecords());
assert.equal(logResult.code, SUCCESS, `log export: ${logResult.error}`);

// Twenty's counter and histogram, collected once and exported as its periodic reader does
class Collect extends MetricReader { constructor() { super({ aggregationTemporalitySelector: () => AggregationTemporality.DELTA }); } async onForceFlush() {} async onShutdown() {} }
const reader = new Collect();
const meter = new MeterProvider({ resource: resourceFromAttributes({ 'service.name': 'twenty-server' }), readers: [reader] }).getMeter('twenty-server');
meter.createCounter('graphql-operation/500').add(1);
meter.createHistogram('twenty_nodejs_eventloop_delay_seconds', { unit: 's' }).record(0.013);
const { resourceMetrics } = await reader.collect();
const metricExporter = new OTLPMetricExporter({ url: process.env.OTLP_COLLECTOR_METRICS_ENDPOINT_URL, temporalityPreference: AggregationTemporality.DELTA });
const metricResult = await exported(metricExporter, resourceMetrics);
assert.equal(metricResult.code, SUCCESS, `metric export: ${metricResult.error}`);
// what the engineer reads back: the sources, the trace by its id, the slow server span, the error log
const traceId = server.spanContext().traceId;
const { traces, logs: logSource } = await sourceIds();
const window = { startTime: new Date(t0 - 36e5).toISOString(), endTime: new Date(t0 + 36e5).toISOString() };
const found = await api('/api/v2/search', { sourceId: traces, ...window, where: `TraceId:${traceId}`, select: 'SpanId,ParentSpanId,SpanName,Duration,StatusCode' });
assert.equal(found.rows, 2);
assert.deepEqual(found.data.map((r) => r.SpanName), ['mongodb.insert', 'POST /api/*'], 'newest first');
assert.equal(found.data[0].ParentSpanId, found.data[1].SpanId);
const slow = await api('/api/v2/search', { sourceId: traces, ...window, where: `TraceId:${traceId} AND ServiceName:librechat AND Duration:>800000000`, select: 'SpanName,Duration,StatusCode' });
assert.deepEqual(slow.data, [{ SpanName: 'POST /api/*', Duration: '850000000', StatusCode: 'Error' }]);
const errors = await api('/api/v2/search', { sourceId: logSource, ...window, where: `SeverityText:error AND TraceId:${traceId}`, select: 'Body,SpanId' });
assert.deepEqual(errors.data, [{ Body: `[saveMessage] Error saving message: ${error.message}`, SpanId: server.spanContext().spanId }]);
console.log(JSON.stringify({ trace: traceId, spans: found.rows, logs: errors.rows, metrics: resourceMetrics.scopeMetrics[0].metrics.length }));
